void Check(string label,bool pass){checks.Add(new{check=label,pass});Console.WriteLine((pass?"PASS ":"FAIL ")+label);if(!pass)throw new InvalidOperationException(label);}
long L(JsonNode n,string key)=>n[key]!.GetValue<long>();StringContent Json(object body)=>new(JsonSerializer.Serialize(body),Encoding.UTF8,"application/json");
async Task<string> Login(string user,string secret){using var client=new HttpClient();client.DefaultRequestHeaders.Add("apikey",publicKey);using var result=await client.PostAsync(authority+"/auth/v1/token?grant_type=password",Json(new{email=user,password=secret}));Check("real Supabase authentication",result.IsSuccessStatusCode);return JsonNode.Parse(await result.Content.ReadAsStringAsync())!["access_token"]!.GetValue<string>();}
async Task<JsonNode?> Call(HttpClient client,string label,HttpMethod method,string url,object? body,int expected,long? revision=null){using var request=new HttpRequestMessage(method,url);if(body is not null)request.Content=Json(body);if(revision.HasValue)request.Headers.TryAddWithoutValidation("If-Match","\""+revision+"\"");using var response=await client.SendAsync(request);Check(label+" HTTP "+(int)response.StatusCode,(int)response.StatusCode==expected);var text=await response.Content.ReadAsStringAsync();return string.IsNullOrWhiteSpace(text)?null:JsonNode.Parse(text);}
async Task<JsonNode> Form(long id)=>(await Call(manager,"read execution",HttpMethod.Get,$"api/qc-forms/{id}",null,200))!;
static async Task<Dictionary<string,Dictionary<string,string>>> Historical(NpgsqlConnection db){
var tables=(await db.QueryAsync<string>("SELECT tablename FROM pg_tables WHERE schemaname='public' ORDER BY tablename")).ToArray();var result=new Dictionary<string,Dictionary<string,string>>();foreach(var table in tables){var key=await db.ExecuteScalarAsync<string>("SELECT a.attname FROM pg_index i JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=ANY(i.indkey) WHERE i.indrelid=CAST(@name AS regclass) AND i.indisprimary ORDER BY a.attnum LIMIT 1",new{name="public.\""+table+"\""});if(key is null)throw new InvalidOperationException("No primary key for preservation baseline");var sql=$"SELECT \"{key}\"::text AS \"Key\",md5((to_jsonb(t)-'Revision'-'HashVersion'-'CoreAuditEventID')::text) AS \"Digest\" FROM public.\"{table}\" t";var rows=await db.QueryAsync<RowDigest>(sql);result[table]=rows.ToDictionary(r=>r.Key,r=>r.Digest);}return result;
}
record RowDigest(string Key,string Digest);
